        .toThrow(/maxTokens must be a positive safe integer/)

      const ctx = new Context()
      await ctx.plugin(LlmRuntime)
      await expect(ctx.plugin(LlmDeepSeek, {
        baseURL: 'http://127.0.0.1:1',
        maxTokens,
